-- MAT-FUNC-004/021/029/039/050/063/064: durable notification dispatch and domain schedulers.

alter table public.notification_deliveries
  add column lease_token uuid,
  add column lease_owner text,
  add column leased_until timestamptz,
  add column terminal_at timestamptz,
  add column provider_idempotency_key text;

alter table public.notification_deliveries add constraint notification_delivery_lease_shape check (
  (lease_token is null and lease_owner is null and leased_until is null)
  or (lease_token is not null and length(lease_owner) between 8 and 160 and leased_until is not null)
);
alter table public.notification_deliveries add constraint notification_delivery_terminal_shape check (
  (status in ('DELIVERED','DEAD_LETTER','SKIPPED'))=(terminal_at is not null)
) not valid;
alter table public.notification_deliveries add constraint notification_provider_idempotency_format check (
  provider_idempotency_key is null or length(provider_idempotency_key) between 16 and 200
);
update public.notification_deliveries set terminal_at=coalesce(updated_at,created_at)
where status in ('DELIVERED','DEAD_LETTER','SKIPPED');
update public.notification_deliveries set provider_idempotency_key='notification-delivery:'||id::text
where channel='EMAIL';
alter table public.notification_deliveries validate constraint notification_delivery_terminal_shape;
create function private.sync_notification_delivery_runtime_shape()returns trigger language plpgsql set search_path=pg_catalog as $$begin
 if new.status in('DELIVERED','DEAD_LETTER','SKIPPED')then new.terminal_at:=coalesce(new.terminal_at,clock_timestamp());new.next_attempt_at:=null;new.lease_token:=null;new.lease_owner:=null;new.leased_until:=null;
 elsif tg_op='UPDATE'and old.status='FAILED'and new.status='PENDING'then new.terminal_at:=null;new.lease_token:=null;new.lease_owner:=null;new.leased_until:=null;
 else new.terminal_at:=null;end if;return new;end$$;
create trigger notification_delivery_runtime_shape before insert or update on public.notification_deliveries for each row execute function private.sync_notification_delivery_runtime_shape();
create unique index notification_provider_idempotency_uidx on public.notification_deliveries(provider_idempotency_key)
  where provider_idempotency_key is not null;
create index notification_delivery_claim_lease_idx on public.notification_deliveries(next_attempt_at,leased_until,id)
  where status in ('PENDING','QUEUED_DIGEST','FAILED');

